let palette = ['#08804e', '#de183c', '#f2b541', '#0496ff', '#ec4e20', '#f991cc', '#4ecdc4', '#af42ae'];

let ctx;
let centerX, centerY;
let triangleSide;
let triangleHeight;
let gridOrigin;
let triangleCells = [];
let gridWidth;
let walkers = [];

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	colorMode(HSB, 360, 100, 100, 100);
	ctx = drawingContext;
	centerX = width / 2;
	centerY = height / 2;
	triangleSide = width / 12;
	triangleHeight = triangleSide / 2 * sqrt(3);
	gridOrigin = createVector(-triangleSide, -triangleHeight / 2);
	gridWidth = width + triangleSide;
	createTriangleGrid();

	for (let i = 0; i < 200; i++) {
		let n = int(random(triangleCells.length));
		let t = triangleCells[n];
		let s = triangleSide * random(0.2, 0.5);
		walkers.push(new Walker(t.x, t.y, s))
	}
}

function draw() {
  // === Variant 1: Neon Kinetic Glitch Modification ===
  dynamicShift = sin((frameCount * speedMult) * 0.08) * 40;

	background('#fff');
	noFill();
	stroke('#00000055');
	strokeWeight(width / 800);
	for (let t of triangleCells) {
		drawTriangle(t.x, t.y, triangleSide, 0);
	}

	for (let w of walkers) {
		w.run();
	}

	noStroke();
	fill(uM_colors[4]);
	for (let t of triangleCells) {
		fill('#000');
		circle(t.x, t.y, triangleSide * 0.08);

		fill('#fff');
		circle(t.x, t.y, triangleSide * 0.02);
	}
}

function createTriangleGrid() {
	let seen = new Set();
	let y = gridOrigin.y;
	let yCounter = 0;

	while (y < gridWidth) {
		let xCounter = 0;
		let x = gridOrigin.x;
		let offsetX = -triangleSide / 2;
		if (yCounter % 2 == 0) {
			offsetX = 0
		}

		while (x < gridWidth) {
			let offsetY = triangleHeight;
			if (xCounter % 2 == 0) {
				offsetY = 0;
			}

			let px = x + offsetX;
			let py = y + offsetY;
			let key = `${px.toFixed(2)}_${py.toFixed(2)}`;

			if (!seen.has(key)) {
				seen.add(key);
				triangleCells.push({
					x: px,
					y: py,
					c: random(palette)
				});
			}
			x += triangleSide / 2;
			xCounter++;
		}

		y += triangleHeight;
		yCounter++;

	}
}

function drawTriangle(x, y, w, a) {
	beginShape();
	vertex(x, y);
	vertex(x + w * cos(a + (PI / 3)), y + w * sin(a + (PI / 3)));
	vertex(x + w * cos(a + (PI / 3) * 2), y + w * sin(a + (PI / 3) * 2));
	endShape(CLOSE);
}

function easeInOutQuart(x) {
	return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
}


/*------------------------------------------------------------------------------------------*/


class Walker {
	constructor(x, y, s) {
		this.x = x;
		this.y = y;
		this.s = s;

		this.curX = x;
		this.curY = y;
		this.clr = random(palette);
		this.reset();
		this.timer = -int(random(120));
		this.curS = 0;
		this.coin = random([-1, 1]);

		this.curW = this.s;
		this.curH = this.s;
	}

	show() {
		stroke('#000');
		noStroke();
		fill(this.clr);
		push();
		translate(this.curX, this.curY);
		rotate(this.angle);
		ellipse(0, 0, this.curW, this.curH);

		pop();
	}

	update() {
		if (0 < this.timer && this.timer < this.t1) {
			let n = norm(this.timer, 0, this.t1 - 1);
			this.curX = lerp(this.x0, this.x1, easeInOutQuart(n));
			this.curY = lerp(this.y0, this.y1, easeInOutQuart(n));
			this.curW = lerp(this.s, this.s * 2, sin(easeInOutQuart(n) * PI));
			this.curH = lerp(this.s, this.s * 0.5, sin(easeInOutQuart(n) * PI));

		}
		if (this.t1 < this.timer) {
			this.reset()
		}
		this.timer++;
	}

	reset() {
		this.timer = -10 * int(random(10));
		let rnd = 1;
		this.t1 = 20 * rnd;

		this.x0 = this.curX;
		this.y0 = this.curY;
		this.angle = int(random(6)) * (TAU / 6);
		let r = triangleSide * rnd;
		let tx = this.x0 + r * cos(this.angle);
		let ty = this.y0 + r * sin(this.angle);
		if (tx < 0 || width < tx || ty < 0 || height < ty) {
			this.t1 = 0;
			this.timer = 0
		}
		if ((abs(this.x0 - this.x1) <= 1) && (abs(this.y0 - this.y1) <= 1)) {
			this.t1 = 0;
			this.timer = 0;
		}
		let margin = max(this.s, 1) / 2;
		tx = constrain(tx, margin, width - margin);
		ty = constrain(ty, margin, height - margin);
		if (typeof triangleCells !== 'undefined' && triangleCells.length > 0) {
			let best = null;
			let bestDist = Infinity;
			for (let t of triangleCells) {
				let d = dist(tx, ty, t.x, t.y);
				if (d < bestDist) {
					bestDist = d;
					best = t;
				}
			}
			if (best && bestDist <= triangleSide * 1.5) {
				this.x1 = best.x;
				this.y1 = best.y;
			} else {
				this.x1 = tx;
				this.y1 = ty;
			}
		} else {
			this.x1 = tx;
			this.y1 = ty;
		}
	}

	run() {
		this.show();
		this.update();
	}
}

